1	// Package incidents holds the incident-handling register: incidents are
2	// created once, evolve through append-only actions under optimistic
3	// concurrency, and link back to events without modifying them.
4	package incidents
5	
6	import (
7		"errors"
8		"fmt"
9		"slices"
10		"strings"
11		"sync"
12		"time"
13	)
14	
15	// Incident statuses.
16	const (
17		StatusOpen     = "open"
18		StatusResolved = "resolved"
19	)
20	
21	// Actions accepted by POST /incidents/{id}/actions. ActionCreate marks the
22	// creation entry in an incident's history.
23	const (
24		ActionCreate            = "create"
25		ActionNote              = "add_note"
26		ActionLinkEvent         = "link_event"
27		ActionResolve           = "resolve"
28		ActionReopen            = "reopen"
29		ActionAddParticipant    = "add_participant"
30		ActionRemoveParticipant = "remove_participant"
31		ActionAssignOwner       = "assign_owner"
32	)
33	
34	// ValidationError reports missing fields, wrong types, or unknown actions.
35	type ValidationError struct{ Reason string }
36	
37	func (e *ValidationError) Error() string { return e.Reason }
38	
39	// NotFoundError reports a missing incident or a missing linked event.
40	type NotFoundError struct{ Reason string }
41	
42	func (e *NotFoundError) Error() string { return e.Reason }
43	
44	// ConflictError carries the current incident version alongside the reason,
45	// so a stale-version response can report it. CurrentVersion is zero when the
46	// conflict is not version-related.
47	type ConflictError struct {
48		Reason         string
49		CurrentVersion int
50	}
51	
52	func (e *ConflictError) Error() string { return e.Reason }
53	
54	// IsValidationError reports whether err is an incident validation failure.
55	func IsValidationError(err error) bool {
56		var target *ValidationError
57		return errors.As(err, &target)
58	}
59	
60	// IsNotFoundError reports whether err is a missing-incident/event failure.
61	func IsNotFoundError(err error) bool {
62		var target *NotFoundError
63		return errors.As(err, &target)
64	}
65	
66	// IsConflictError reports whether err is an incident conflict failure.
67	func IsConflictError(err error) bool {
68		var target *ConflictError
69		return errors.As(err, &target)
70	}
71	
72	// CurrentVersionOf returns the version reported with a version conflict, or
73	// zero when err is not a version conflict.
74	func CurrentVersionOf(err error) int {
75		var target *ConflictError
76		if errors.As(err, &target) {
77			return target.CurrentVersion
78		}
79		return 0
80	}
81	
82	func validationErr(format string, args ...any) error {
83		return &ValidationError{Reason: fmt.Sprintf(format, args...)}
84	}
85	
86	func notFoundErr(format string, args ...any) error {
87		return &NotFoundError{Reason: fmt.Sprintf(format, args...)}
88	}
89	
90	func conflictErr(currentVersion int, format string, args ...any) error {
91		return &ConflictError{Reason: fmt.Sprintf(format, args...), CurrentVersion: currentVersion}
92	}
93	
94	// Creation is the normalized content of POST /incidents. Strings are trimmed
95	// of surrounding whitespace but keep their interior case.
96	type Creation struct {
97		ID       string
98		Title    string
99		Service  string
100		Operator string
101	}
102	
103	// Request is the normalized content of POST /incidents/{id}/actions. Content
104	// carries the action payload: the note text, the linked event id, or the
105	// resolve/reopen reason.
106	type Request struct {
107		IncidentID      string
108		ActionID        string
109		Operator        string
110		ExpectedVersion int
111		Type            string
112		Content         string
113	}
114	
115	// CreateResult is the result of a successful create, including an idempotent
116	// replay.
117	type CreateResult struct {
118		ID      string
119		Status  string
120		Version int
121	}
122	
123	// ActionResult is the result of a successful action, including an idempotent
124	// replay.
125	type ActionResult struct {
126		IncidentID string
127		ActionID   string
128		Version    int
129	}
130	
131	// Entry is one committed item in an incident's history: the creation itself
132	// or a later action.
133	type Entry struct {
134		ActionID string
135		Operator string
136		Action   string
137		Content  string
138		Version  int
139		At       time.Time
140	}
141	
142	// Incident is one committed snapshot, suitable for a single-version read.
143	type Incident struct {
144		ID           string
145		Title        string
146		Service      string
147		Status       string
148		Version      int
149		Participants []string
150		Owner        string
151		Links        []string
152		History      []Entry
153	}
154	
155	// EventLookup resolves an event id without exposing the whole timeline, so
156	// incident handling never modifies events.
157	type EventLookup interface {
158		// LookupEvent returns (service, true) for a stored event, or ("", false).
159		LookupEvent(id string) (service string, ok bool)
160	}
161	
162	// BeforeCommit persists one new record while the registry lock is held and
163	// before the in-memory state advances. Returning an error rejects the request
164	// without touching the incident.
165	type BeforeCommit func(record Record) error
166	
167	// Registry is the concurrency-safe set of incidents.
168	type Registry struct {
169		mu        sync.Mutex
170		incidents map[string]*incidentState
171	
172		events       EventLookup
173		beforeCommit BeforeCommit
174		now          func() time.Time
175	}
176	
177	// incidentState is the mutable state of one incident.
178	type incidentState struct {
179		id      string
180		title   string
181		service string
182		status  string
183		version int
184	
185		// participants holds every participant name in membership order; the
186		// membership is tracked separately by participantSet. The owner is always
187		// among the participants. A newly created incident starts with only its
188		// operator as both participant and owner; note/link operators never join
189		// automatically.
190		participants   []string
191		participantSet map[string]struct{}
192		owner          string
193	
194		links   []string
195		linkSet map[string]struct{}
196	
197		history []Entry
198		// actions remembers each successful action's normalized request and the
199		// version reached afterwards, so an identical retry replays the first
200		// result even once the version has moved on.
201		actions map[string]committedAction
202	
203		creation Creation
204	}
205	
206	type committedAction struct {
207		request       Request
208		resultVersion int
209	}
210	
211	// Option configures a Registry at construction.
212	type Option func(*Registry)
213	
214	// WithClock overrides the server clock, mainly for tests.
215	func WithClock(now func() time.Time) Option {
216		return func(r *Registry) {
217			if now != nil {
218				r.now = now
219			}
220		}
221	}
222	
223	// NewRegistry returns an empty registry. events resolves linked event ids and
224	// beforeCommit durably stores each accepted record.
225	func NewRegistry(events EventLookup, beforeCommit BeforeCommit, opts ...Option) *Registry {
226		r := &Registry{
227			incidents:    make(map[string]*incidentState),
228			events:       events,
229			beforeCommit: beforeCommit,
230			now:          func() time.Time { return time.Now().UTC() },
231		}
232		for _, opt := range opts {
233			opt(r)
234		}
235		return r
236	}
237	
238	// NormalizeCreation trims the four creation fields, keeping their interior
239	// case, and requires each to be non-empty afterwards.
240	func NormalizeCreation(input Creation) (Creation, error) {
241		var err error
242		if input.ID, err = trimRequired("id", input.ID); err != nil {
243			return Creation{}, err
244		}
245		if input.Title, err = trimRequired("title", input.Title); err != nil {
246			return Creation{}, err
247		}
248		if input.Service, err = trimRequired("service", input.Service); err != nil {
249			return Creation{}, err
250		}
251		if input.Operator, err = trimRequired("operator", input.Operator); err != nil {
252			return Creation{}, err
253		}
254		return input, nil
255	}
256	
257	// NormalizeRequest trims and validates one action request. incidentID comes
258	// from the URL path and is only checked for emptiness.
259	func NormalizeRequest(input Request) (Request, error) {
260		var err error
261		if input.IncidentID, err = trimRequired("incident id", input.IncidentID); err != nil {
262			return Request{}, err
263		}
264		if input.ActionID, err = trimRequired("action_id", input.ActionID); err != nil {
265			return Request{}, err
266		}
267		if input.Operator, err = trimRequired("operator", input.Operator); err != nil {
268			return Request{}, err
269		}
270		if input.ExpectedVersion <= 0 {
271			return Request{}, validationErr("expected_version must be a positive integer")
272		}
273		switch input.Type {
274		case ActionNote, ActionLinkEvent, ActionResolve, ActionReopen,
275			ActionAddParticipant, ActionRemoveParticipant, ActionAssignOwner:
276		default:
277			return Request{}, validationErr("unknown action %q", input.Type)
278		}
279		if input.Content, err = trimRequired(actionContentField(input.Type), input.Content); err != nil {
280			return Request{}, err
281		}
282		return input, nil
283	}
284	
285	// actionContentField names the request member that carries each action's
286	// payload, used in validation messages.
287	func actionContentField(action string) string {
288		switch action {
289		case ActionLinkEvent:
290			return "event_id"
291		case ActionResolve, ActionReopen:
292			return "reason"
293		case ActionAddParticipant, ActionRemoveParticipant, ActionAssignOwner:
294			return "participant"
295		default:
296			return "content"
297		}
298	}
299	
300	func trimRequired(field, value string) (string, error) {
301		value = strings.TrimSpace(value)
302		if value == "" {
303			return "", validationErr("%s must not be empty", field)
304		}
305		return value, nil
306	}
307	
308	// Create accepts a new incident or replays an identical creation. A stored id
309	// presented with different normalized content conflicts.
310	func (r *Registry) Create(input Creation) (CreateResult, error) {
311		creation, err := NormalizeCreation(input)
312		if err != nil {
313			return CreateResult{}, err
314		}
315	
316		r.mu.Lock()
317		defer r.mu.Unlock()
318	
319		if existing, ok := r.incidents[creation.ID]; ok {
320			if existing.creation != creation {
321				return CreateResult{}, conflictErr(existing.version,
322					"incident %q already exists with different content", creation.ID)
323			}
324			// A creation replay returns the first result verbatim: open at
325			// version 1, even if the incident has moved on since.
326			return CreateResult{ID: creation.ID, Status: StatusOpen, Version: 1}, nil
327		}
328	
329		at := r.now()
330		record := NewCreationRecord(creation, at)
331		if r.beforeCommit != nil {
332			if err := r.beforeCommit(record); err != nil {
333				return CreateResult{}, err
334			}
335		}
336		r.incidents[creation.ID] = newIncidentState(creation, at)
337		return CreateResult{ID: creation.ID, Status: StatusOpen, Version: 1}, nil
338	}
339	
340	// Apply accepts one action or replays an identical one. Validation and every
341	// state check happen under the registry lock before persistence, so a
342	// rejected request leaves the incident untouched.
343	func (r *Registry) Apply(input Request) (ActionResult, error) {
344		req, err := NormalizeRequest(input)
345		if err != nil {
346			return ActionResult{}, err
347		}
348	
349		r.mu.Lock()
350		defer r.mu.Unlock()
351	
352		state, ok := r.incidents[req.IncidentID]
353		if !ok {
354			return ActionResult{}, notFoundErr("incident %q not found", req.IncidentID)
355		}
356	
357		// Idempotent replay is checked first: a retry of the first successful
358		// request still returns that result even though its expected_version is
359		// stale by now.
360		if prior, repeated := state.actions[req.ActionID]; repeated {
361			if prior.request != req {
362				return ActionResult{}, conflictErr(state.version,
363					"action %q already exists with different content", req.ActionID)
364			}
365			return ActionResult{IncidentID: state.id, ActionID: req.ActionID, Version: prior.resultVersion}, nil
366		}
367	
368		if err := r.checkAction(state, req); err != nil {
369			return ActionResult{}, err
370		}
371	
372		at := r.now()
373		if r.beforeCommit != nil {
374			if err := r.beforeCommit(NewActionRecord(req, at)); err != nil {
375				return ActionResult{}, err
376			}
377		}
378		version := state.commit(req, at)
379		return ActionResult{IncidentID: state.id, ActionID: req.ActionID, Version: version}, nil
380	}
381	
382	// checkAction enforces optimistic versioning, the open/resolved state
383	// machine, and the link rules. It runs with the registry lock held.
384	func (r *Registry) checkAction(state *incidentState, req Request) error {
385		if req.ExpectedVersion != state.version {
386			return conflictErr(state.version,
387				"expected version %d but incident %q is at version %d",
388				req.ExpectedVersion, state.id, state.version)
389		}
390		switch req.Type {
391		case ActionNote:
392			if state.status != StatusOpen {
393				return conflictErr(state.version, "cannot add a note to a %s incident", state.status)
394			}
395		case ActionLinkEvent:
396			if err := r.linkConflictError(state, req); err != nil {
397				return err
398			}
399		case ActionResolve:
400			if state.status != StatusOpen {
401				return conflictErr(state.version, "incident %q is already resolved", state.id)
402			}
403		case ActionReopen:
404			if state.status != StatusResolved {
405				return conflictErr(state.version, "incident %q is not resolved", state.id)
406			}
407		case ActionAddParticipant, ActionRemoveParticipant, ActionAssignOwner:
408			if err := personnelConflictError(state, req); err != nil {
409				return err
410			}
411		}
412		return nil
413	}
414	
415	// linkViolation identifies one broken link_event eligibility rule without
416	// binding it to an error vocabulary: the live request path turns it into a
417	// 404/409 in its own wording, while startup replay turns it into a log
418	// inconsistency. Keeping the judgment independent of the wording means both
419	// entry paths enforce the very same business constraints.
420	type linkViolation int
421	
422	const (
423		linkOK linkViolation = iota
424		// linkClosed: a link was attempted while the incident was not open.
425		linkClosed
426		// linkMissing: the event id does not resolve in the event log (or there
427		// is no event lookup at all).
428		linkMissing
429		// linkWrongService: the event belongs to a different service.
430		linkWrongService
431		// linkAlreadyLinked: the incident already links this event.
432		linkAlreadyLinked
433	)
434	
435	// checkLinkEligibility evaluates the link rules shared by the live request
436	// path and startup replay: an event may be linked only while the incident is
437	// open, only when it exists and belongs to the incident's service, and only
438	// once per incident. It needs the registry solely to resolve events; every
439	// other input comes from the in-progress state and the normalized request.
440	// The returned service is the resolved event's service when the event was
441	// found, so the callers never have to look it up a second time.
442	func (r *Registry) checkLinkEligibility(state *incidentState, req Request) (linkViolation, string) {
443		if state.status != StatusOpen {
444			return linkClosed, ""
445		}
446		if r.events == nil {
447			return linkMissing, ""
448		}
449		service, found := r.events.LookupEvent(req.Content)
450		if !found {
451			return linkMissing, ""
452		}
453		if service != state.service {
454			return linkWrongService, service
455		}
456		if _, linked := state.linkSet[req.Content]; linked {
457			return linkAlreadyLinked, service
458		}
459		return linkOK, service
460	}
461	
462	// linkConflictError renders a shared link violation in the live request
463	// path's vocabulary: a missing event is a 404, every other violation is a
464	// 409-style conflict carrying the current version.
465	func (r *Registry) linkConflictError(state *incidentState, req Request) error {
466		switch violation, service := r.checkLinkEligibility(state, req); violation {
467		case linkOK:
468			return nil
469		case linkClosed:
470			return conflictErr(state.version, "cannot link an event to a %s incident", state.status)
471		case linkMissing:
472			return notFoundErr("event %q not found", req.Content)
473		case linkWrongService:
474			return conflictErr(state.version,
475				"event %q belongs to service %q, not %q", req.Content, service, state.service)
476		case linkAlreadyLinked:
477			return conflictErr(state.version,
478				"event %q is already linked to incident %q", req.Content, state.id)
479		}
480		return nil
481	}
482	
483	// personnelViolation identifies one broken personnel rule without binding
484	// it to an error vocabulary: the live request path turns it into a conflict
485	// carrying the current version, while startup replay turns it into a log
486	// inconsistency. Keeping the judgment independent of the wording means both
487	// entry paths enforce the very same business constraints.
488	type personnelViolation int
489	
490	const (
491		personnelOK personnelViolation = iota
492		// personnelClosed: a personnel action was attempted while not open.
493		personnelClosed
494		// personnelAlreadyMember: the add target already participates.
495		personnelAlreadyMember
496		// personnelNotMember: the remove target does not participate.
497		personnelNotMember
498		// personnelRemoveOwner: the remove target is the current owner.
499		personnelRemoveOwner
500		// personnelOwnerNonMember: the handover target does not participate.
501		personnelOwnerNonMember
502		// personnelOwnerUnchanged: the handover target is already the owner.
503		personnelOwnerUnchanged
504	)
505	
506	// checkPersonnelAction evaluates the personnel rules shared by the live
507	// request path and startup replay: personnel actions are accepted only
508	// while the incident is open; an added person must not already participate;
509	// a removed person must participate without being the current owner; an
510	// owner handover must target a different, already participating person.
511	func checkPersonnelAction(state *incidentState, req Request) personnelViolation {
512		if state.status != StatusOpen {
513			return personnelClosed
514		}
515		switch req.Type {
516		case ActionAddParticipant:
517			if _, member := state.participantSet[req.Content]; member {
518				return personnelAlreadyMember
519			}
520		case ActionRemoveParticipant:
521			if _, member := state.participantSet[req.Content]; !member {
522				return personnelNotMember
523			}
524			if req.Content == state.owner {
525				return personnelRemoveOwner
526			}
527		case ActionAssignOwner:
528			if _, member := state.participantSet[req.Content]; !member {
529				return personnelOwnerNonMember
530			}
531			if req.Content == state.owner {
532				return personnelOwnerUnchanged
533			}
534		}
535		return personnelOK
536	}
537	
538	// personnelConflictError renders a shared personnel violation in the live
539	// request path's vocabulary: a 409-style conflict carrying the current
540	// version.
541	func personnelConflictError(state *incidentState, req Request) error {
542		switch checkPersonnelAction(state, req) {
543		case personnelOK:
544			return nil
545		case personnelClosed:
546			return conflictErr(state.version, "cannot %s on a %s incident", participantRuleName(req.Type), state.status)
547		case personnelAlreadyMember:
548			return conflictErr(state.version, "%q is already a participant of incident %q", req.Content, state.id)
549		case personnelNotMember:
550			return conflictErr(state.version, "%q is not a participant of incident %q", req.Content, state.id)
551		case personnelRemoveOwner:
552			return conflictErr(state.version, "cannot remove the current owner %q from incident %q", req.Content, state.id)
553		case personnelOwnerNonMember:
554			return conflictErr(state.version, "cannot hand incident %q to non-participant %q", state.id, req.Content)
555		case personnelOwnerUnchanged:
556			return conflictErr(state.version, "%q is already the owner of incident %q", req.Content, state.id)
557		}
558		return nil
559	}
560	
561	// participantRuleName renders the personnel action names in error messages.
562	func participantRuleName(action string) string {
563		switch action {
564		case ActionAddParticipant:
565			return "add a participant"
566		case ActionRemoveParticipant:
567			return "remove a participant"
568		case ActionAssignOwner:
569			return "hand over ownership"
570		default:
571			return action
572		}
573	}
574	
575	// Get returns a point-in-time copy of one incident. The copy's people,
576	// status, links, version, and history all belong to the same committed
577	// version.
578	func (r *Registry) Get(id string) (Incident, error) {
579		r.mu.Lock()
580		defer r.mu.Unlock()
581		state, ok := r.incidents[id]
582		if !ok {
583			return Incident{}, notFoundErr("incident %q not found", id)
584		}
585		return state.snapshot(), nil
586	}
587	
588	func newIncidentState(creation Creation, at time.Time) *incidentState {
589		return &incidentState{
590			id:             creation.ID,
591			title:          creation.Title,
592			service:        creation.Service,
593			status:         StatusOpen,
594			version:        1,
595			participants:   []string{creation.Operator},
596			participantSet: map[string]struct{}{creation.Operator: {}},
597			owner:          creation.Operator,
598			links:          []string{},
599			linkSet:        make(map[string]struct{}),
600			actions:        make(map[string]committedAction),
601			history:        []Entry{{Operator: creation.Operator, Action: ActionCreate, Content: creation.Title, Version: 1, At: at}},
602			creation:       creation,
603		}
604	}
605	
606	// commit advances the state by one already-validated action and returns the
607	// new version.
608	func (s *incidentState) commit(req Request, at time.Time) int {
609		switch req.Type {
610		case ActionLinkEvent:
611			s.linkSet[req.Content] = struct{}{}
612			s.links = append(s.links, req.Content)
613		case ActionResolve:
614			s.status = StatusResolved
615		case ActionReopen:
616			s.status = StatusOpen
617		case ActionAddParticipant:
618			s.participantSet[req.Content] = struct{}{}
619			s.participants = append(s.participants, req.Content)
620		case ActionRemoveParticipant:
621			delete(s.participantSet, req.Content)
622			s.participants = removeString(s.participants, req.Content)
623		case ActionAssignOwner:
624			s.owner = req.Content
625		}
626		s.version++
627		s.history = append(s.history, Entry{
628			ActionID: req.ActionID,
629			Operator: req.Operator,
630			Action:   req.Type,
631			Content:  req.Content,
632			Version:  s.version,
633			At:       at,
634		})
635		s.actions[req.ActionID] = committedAction{request: req, resultVersion: s.version}
636		return s.version
637	}
638	
639	// removeString drops the first occurrence of value, preserving order.
640	func removeString(values []string, value string) []string {
641		for i, v := range values {
642			if v == value {
643				return append(values[:i], values[i+1:]...)
644			}
645		}
646		return values
647	}
648	
649	func (s *incidentState) snapshot() Incident {
650		links := slices.Clone(s.links)
651		history := make([]Entry, len(s.history))
652		copy(history, s.history)
653		participants := append([]string{}, s.participants...)
654		slices.Sort(participants)
655		return Incident{
656			ID:           s.id,
657			Title:        s.title,
658			Service:      s.service,
659			Status:       s.status,
660			Version:      s.version,
661			Participants: participants,
662			Owner:        s.owner,
663			Links:        links,
664			History:      history,
665		}
666	}
667

