1	package incidents
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"time"
10	)
11	
12	// Record kinds persisted in the durable incident log, one record per
13	// successfully committed creation or action.
14	const (
15		RecordCreation = "create"
16		RecordAction   = "action"
17	)
18	
19	// StoredAction is one committed action with its server timestamp.
20	type StoredAction struct {
21		Request Request
22		At      time.Time
23	}
24	
25	// Record is the unit of durable storage and of replay. Exactly one of
26	// Creation or Action is set, matching Kind.
27	type Record struct {
28		Kind     string
29		Creation *Creation
30		Action   *StoredAction
31		At       time.Time
32	}
33	
34	// NewCreationRecord assembles the durable record for a creation.
35	func NewCreationRecord(creation Creation, at time.Time) Record {
36		c := creation
37		return Record{Kind: RecordCreation, Creation: &c, At: at}
38	}
39	
40	// NewActionRecord assembles the durable record for an action.
41	func NewActionRecord(req Request, at time.Time) Record {
42		a := StoredAction{Request: req, At: at}
43		return Record{Kind: RecordAction, Action: &a, At: at}
44	}
45	
46	// recordDTO is the JSON frame payload for one record. Timestamps use
47	// RFC3339Nano with a UTC location.
48	type recordDTO struct {
49		Kind     string       `json:"kind"`
50		At       time.Time    `json:"at"`
51		Creation *creationDTO `json:"creation,omitempty"`
52		Action   *actionDTO   `json:"action,omitempty"`
53	}
54	
55	type creationDTO struct {
56		ID       string `json:"id"`
57		Title    string `json:"title"`
58		Service  string `json:"service"`
59		Operator string `json:"operator"`
60	}
61	
62	type actionDTO struct {
63		IncidentID      string `json:"incident_id"`
64		ActionID        string `json:"action_id"`
65		Operator        string `json:"operator"`
66		ExpectedVersion int    `json:"expected_version"`
67		Type            string `json:"type"`
68		Content         string `json:"content"`
69	}
70	
71	// MarshalRecord encodes one record as a strict JSON object.
72	func MarshalRecord(record Record) ([]byte, error) {
73		dto := recordDTO{Kind: record.Kind, At: record.At.UTC()}
74		switch record.Kind {
75		case RecordCreation:
76			if record.Creation == nil {
77				return nil, fmt.Errorf("creation record is missing its content")
78			}
79			dto.Creation = &creationDTO{
80				ID:       record.Creation.ID,
81				Title:    record.Creation.Title,
82				Service:  record.Creation.Service,
83				Operator: record.Creation.Operator,
84			}
85		case RecordAction:
86			if record.Action == nil {
87				return nil, fmt.Errorf("action record is missing its content")
88			}
89			dto.Action = &actionDTO{
90				IncidentID:      record.Action.Request.IncidentID,
91				ActionID:        record.Action.Request.ActionID,
92				Operator:        record.Action.Request.Operator,
93				ExpectedVersion: record.Action.Request.ExpectedVersion,
94				Type:            record.Action.Request.Type,
95				Content:         record.Action.Request.Content,
96			}
97		default:
98			return nil, fmt.Errorf("unknown record kind %q", record.Kind)
99		}
100		return json.Marshal(dto)
101	}
102	
103	// DecodeRecord strictly decodes one record frame and re-validates it, so a
104	// frame containing illegal data is rejected as corruption at startup.
105	func DecodeRecord(data []byte) (Record, error) {
106		dec := json.NewDecoder(bytes.NewReader(data))
107		dec.DisallowUnknownFields()
108		var dto recordDTO
109		if err := dec.Decode(&dto); err != nil {
110			return Record{}, fmt.Errorf("decode incident record: %w", err)
111		}
112		var extra json.RawMessage
113		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
114			if err == nil {
115				return Record{}, fmt.Errorf("decode incident record: unexpected trailing data")
116			}
117			return Record{}, fmt.Errorf("decode incident record: %w", err)
118		}
119		if dto.At.IsZero() {
120			return Record{}, fmt.Errorf("incident record is missing its timestamp")
121		}
122	
123		record := Record{Kind: dto.Kind, At: dto.At.UTC()}
124		switch dto.Kind {
125		case RecordCreation:
126			if dto.Creation == nil || dto.Action != nil {
127				return Record{}, fmt.Errorf("creation record has the wrong shape")
128			}
129			creation := Creation{
130				ID:       dto.Creation.ID,
131				Title:    dto.Creation.Title,
132				Service:  dto.Creation.Service,
133				Operator: dto.Creation.Operator,
134			}
135			if _, err := NormalizeCreation(creation); err != nil {
136				return Record{}, err
137			}
138			record.Creation = &creation
139		case RecordAction:
140			if dto.Action == nil || dto.Creation != nil {
141				return Record{}, fmt.Errorf("action record has the wrong shape")
142			}
143			req := Request{
144				IncidentID:      dto.Action.IncidentID,
145				ActionID:        dto.Action.ActionID,
146				Operator:        dto.Action.Operator,
147				ExpectedVersion: dto.Action.ExpectedVersion,
148				Type:            dto.Action.Type,
149				Content:         dto.Action.Content,
150			}
151			if _, err := NormalizeRequest(req); err != nil {
152				return Record{}, err
153			}
154			record.Action = &StoredAction{Request: req, At: dto.At.UTC()}
155		default:
156			return Record{}, fmt.Errorf("unknown record kind %q", dto.Kind)
157		}
158		return record, nil
159	}
