196	func TestPersonnelActionReplayAcrossChanges(t *testing.T) {
197		reg, _, _ := newTestRegistry(&fakeEvents{})
198		_, _ = reg.Create(validCreation())
199	
200		// Add Carol, add Eve, hand ownership to Eve, remove Carol, resolve.
201		first := Request{IncidentID: "INC-1", ActionID: "p1", Operator: "alice",
202			ExpectedVersion: 1, Type: ActionAddParticipant, Content: "Carol"}
203		res, err := reg.Apply(first)
204		if err != nil {
205			t.Fatal(err)
206		}
207		must := func(req Request) {
208			t.Helper()
209			if _, err := reg.Apply(req); err != nil {
210				t.Fatal(err)
211			}
212		}
213		must(Request{IncidentID: "INC-1", ActionID: "p2", Operator: "alice",
214			ExpectedVersion: 2, Type: ActionAddParticipant, Content: "Eve"})
215		must(Request{IncidentID: "INC-1", ActionID: "o1", Operator: "alice",
