221	
222		// Even with the incident resolved and Carol long removed, retrying the
223		// original add returns its first result and restores nothing: Carol stays
224		// absent, Eve stays owner, and the version does not move.
225		replay, err := reg.Apply(first)
226		if err != nil {
227			t.Fatalf("replay: %v", err)
228		}
229		if replay != res {
230			t.Fatalf("replay %+v want %+v", replay, res)
231		}
232		inc, _ := reg.Get("INC-1")
233		if inc.Version != 6 {
234			t.Fatalf("replay must not advance version: %d", inc.Version)
235		}
236		if !reflect.DeepEqual(inc.Participants, []string{"Alice", "Eve"}) {
237			t.Fatalf("replay must not restore membership: %+v", inc.Participants)
238		}
239		if inc.Owner != "Eve" {
240			t.Fatalf("replay must not touch owner: %q", inc.Owner)
241		}
242	
243		// Same action id with changed content is a conflict even after resolution.
244		_, err = reg.Apply(Request{IncidentID: "INC-1", ActionID: "p1", Operator: "alice",
245			ExpectedVersion: 6, Type: ActionAddParticipant, Content: "Dave"})
246		if !IsConflictError(err) {
247			t.Fatalf("changed replay: %v", err)
248		}
249	}
