251	func TestPersonnelReplayRebuildsState(t *testing.T) {
252		times := seededTimes(7)
253		records := []Record{
254			NewCreationRecord(Creation{ID: "I1", Title: "T", Service: "gateway", Operator: "alice"}, times[0]),
255			NewActionRecord(Request{IncidentID: "I1", ActionID: "p1", Operator: "alice", ExpectedVersion: 1, Type: ActionAddParticipant, Content: "bob"}, times[1]),
256			NewActionRecord(Request{IncidentID: "I1", ActionID: "p2", Operator: "alice", ExpectedVersion: 2, Type: ActionAddParticipant, Content: "carol"}, times[2]),
257			NewActionRecord(Request{IncidentID: "I1", ActionID: "o1", Operator: "alice", ExpectedVersion: 3, Type: ActionAssignOwner, Content: "bob"}, times[3]),
258			NewActionRecord(Request{IncidentID: "I1", ActionID: "r1", Operator: "bob", ExpectedVersion: 4, Type: ActionResolve, Content: "done"}, times[4]),
259			NewActionRecord(Request{IncidentID: "I1", ActionID: "o2", Operator: "bob", ExpectedVersion: 5, Type: ActionReopen, Content: "again"}, times[5]),
260			NewActionRecord(Request{IncidentID: "I1", ActionID: "p3", Operator: "bob", ExpectedVersion: 6, Type: ActionRemoveParticipant, Content: "carol"}, times[6]),
261		}
262	
263		reg := NewRegistry(&fakeEvents{}, nil)
264		for _, record := range records {
265			if err := reg.Load(record); err != nil {
266				t.Fatalf("load: %v", err)
267			}
268		}
269		inc, _ := reg.Get("I1")
270		if inc.Owner != "bob" {
271			t.Fatalf("rebuilt owner %q", inc.Owner)
272		}
273		if !reflect.DeepEqual(inc.Participants, []string{"alice", "bob"}) {
274			t.Fatalf("rebuilt participants %+v", inc.Participants)
