48			"unknown action":   `{"kind":"action","at":"2026-10-01T12:00:00Z","action":{"incident_id":"i","action_id":"a","operator":"o","expected_version":1,"type":"boom","content":"c"}}`,
49			"zero exp version": `{"kind":"action","at":"2026-10-01T12:00:00Z","action":{"incident_id":"i","action_id":"a","operator":"o","expected_version":0,"type":"add_note","content":"c"}}`,
