194			// is resolved: the shared link eligibility check must reject it.
195			link := NewActionRecord(Request{IncidentID: "I1", ActionID: "l", Operator: "o", ExpectedVersion: 2, Type: ActionLinkEvent, Content: "e1"}, t0.Add(2*time.Second))
196			if err := reg.Load(link); err == nil {
197				t.Fatal("a link on a resolved incident must fail recovery")
198			}
