12	// IncidentStorage durably persists an incident record before it becomes
13	// visible and reports whether incident storage has failed.
14	type IncidentStorage interface {
15		AppendRecord(record incidents.Record) error
16		Poisoned() bool
17	}
18	
19	// Allowed top-level members for the two incident request bodies.
20	var (
21		allowedIncidentCreateFields = map[string]struct{}{
22			"id":       {},
23			"title":    {},
24			"service":  {},
25			"operator": {},
26		}
27		allowedIncidentActionFields = map[string]struct{}{
28			"action_id":        {},
29			"operator":         {},
30			"expected_version": {},
31			"action":           {},
32			"content":          {},
33			"event_id":         {},
34			"reason":           {},
35			"participant":      {},
36		}
37	)
