39	type createIncidentResponse struct {
40		ID      string `json:"id"`
41		Status  string `json:"status"`
42		Version int    `json:"version"`
43	}
44	
45	type actionResponse struct {
46		IncidentID string `json:"incident_id"`
47		ActionID   string `json:"action_id"`
48		Version    int    `json:"version"`
49	}
50	
51	func (h *Handler) incidentsRoot(w http.ResponseWriter, r *http.Request) {
52		if r.Method != http.MethodPost {
53			w.Header().Set("Allow", "POST")
54			writeError(w, http.StatusMethodNotAllowed, "method not allowed")
55			return
56		}
57		h.createIncident(w, r)
58	}
