60	func (h *Handler) incidentItem(w http.ResponseWriter, r *http.Request) {
61		if r.Method != http.MethodGet {
62			w.Header().Set("Allow", "GET")
63			writeError(w, http.StatusMethodNotAllowed, "method not allowed")
64			return
65		}
66		if h.incidentStoreUnavailable(w) {
67			return
68		}
69	
70		id := r.PathValue("id")
71		inc, err := h.incidents.Get(id)
72		if err != nil {
73			writeIncidentError(w, err)
74			return
75		}
76		writeIncident(w, h, inc)
77	}
78	
79	func (h *Handler) incidentActions(w http.ResponseWriter, r *http.Request) {
80		if r.Method != http.MethodPost {
81			w.Header().Set("Allow", "POST")
82			writeError(w, http.StatusMethodNotAllowed, "method not allowed")
83			return
84		}
85		h.addAction(w, r)
86	}
87	
88	func (h *Handler) createIncident(w http.ResponseWriter, r *http.Request) {
89		if h.incidentStoreUnavailable(w) {
90			return
91		}
92	
93		body, err := readJSONObjectBody(w, r, allowedIncidentCreateFields)
94		if err != nil {
95			writeError(w, http.StatusBadRequest, "invalid JSON body")
96			return
97		}
98	
99		creation := incidents.Creation{
100			ID:       stringField(body, "id"),
101			Title:    stringField(body, "title"),
102			Service:  stringField(body, "service"),
103			Operator: stringField(body, "operator"),
104		}
105		result, aerr := h.incidents.Create(creation)
106		if aerr != nil {
107			writeIncidentError(w, aerr)
108			return
109		}
110		writeJSON(w, http.StatusOK, createIncidentResponse{
111			ID: result.ID, Status: result.Status, Version: result.Version,
112		})
113	}
114	
115	func (h *Handler) addAction(w http.ResponseWriter, r *http.Request) {
116		if h.incidentStoreUnavailable(w) {
117			return
118		}
119	
120		body, err := readJSONObjectBody(w, r, allowedIncidentActionFields)
121		if err != nil {
122			writeError(w, http.StatusBadRequest, "invalid JSON body")
123			return
124		}
125	
126		req, ok := decodeActionRequest(w, r.PathValue("id"), body)
127		if !ok {
128			return
129		}
130	
131		result, aerr := h.incidents.Apply(req)
132		if aerr != nil {
133			writeIncidentError(w, aerr)
134			return
135		}
136		writeJSON(w, http.StatusOK, actionResponse{
137			IncidentID: result.IncidentID, ActionID: result.ActionID, Version: result.Version,
138		})
139	}
140	
141	// decodeActionRequest validates the common fields and the one payload member
142	// the named action requires. Any payload member that does not belong to the
143	// action is rejected, so each action has an exact, unambiguous shape.
144	func decodeActionRequest(w http.ResponseWriter, incidentID string, fields map[string]json.RawMessage) (incidents.Request, bool) {
145		actionID, ok := requiredString(w, fields, "action_id")
146		if !ok {
147			return incidents.Request{}, false
148		}
149		operator, ok := requiredString(w, fields, "operator")
150		if !ok {
151			return incidents.Request{}, false
152		}
153		action, ok := requiredString(w, fields, "action")
154		if !ok {
155			return incidents.Request{}, false
156		}
157	
158		raw, present := fields["expected_version"]
159		if !present {
160			writeError(w, http.StatusBadRequest, "expected_version is required")
161			return incidents.Request{}, false
162		}
163		var expected int64
164		if !decodeStrictInt(w, raw, "expected_version", &expected) {
165			return incidents.Request{}, false
166		}
167	
168		payloadField, valid := actionPayloadField(action)
169		if !valid {
170			writeError(w, http.StatusBadRequest, "unknown action")
171			return incidents.Request{}, false
172		}
173		content, ok := requiredString(w, fields, payloadField)
174		if !ok {
175			return incidents.Request{}, false
176		}
177		for _, extra := range []string{"content", "event_id", "reason", "participant"} {
178			if extra == payloadField {
179				continue
180			}
181			if _, present := fields[extra]; present {
182				writeError(w, http.StatusBadRequest, "unexpected field "+extra+" for action "+action)
183				return incidents.Request{}, false
184			}
185		}
186	
187		return incidents.Request{
188			IncidentID:      incidentID,
189			ActionID:        actionID,
190			Operator:        operator,
191			ExpectedVersion: int(expected),
192			Type:            action,
193			Content:         content,
194		}, true
195	}
196	
197	// actionPayloadField maps an action name to the member carrying its payload.
198	func actionPayloadField(action string) (string, bool) {
199		switch action {
200		case incidents.ActionNote:
201			return "content", true
202		case incidents.ActionLinkEvent:
203			return "event_id", true
204		case incidents.ActionResolve, incidents.ActionReopen:
205			return "reason", true
206		case incidents.ActionAddParticipant, incidents.ActionRemoveParticipant, incidents.ActionAssignOwner:
207			return "participant", true
208		default:
209			return "", false
210		}
211	}
212	
213	func (h *Handler) incidentStoreUnavailable(w http.ResponseWriter) bool {
214		if h.incidentLogs == nil || h.incidentLogs.Poisoned() {
215			writeError(w, http.StatusServiceUnavailable, "incident storage is unavailable; restart required")
216			return true
217		}
218		return false
219	}
220	
221	// writeIncidentError maps domain errors onto the documented statuses. A
222	// version conflict additionally reports the current version.
223	func writeIncidentError(w http.ResponseWriter, err error) {
224		switch {
225		case incidents.IsValidationError(err):
226			writeError(w, http.StatusBadRequest, err.Error())
227		case incidents.IsNotFoundError(err):
228			writeError(w, http.StatusNotFound, err.Error())
229		case incidents.IsConflictError(err):
230			current := incidents.CurrentVersionOf(err)
231			if current > 0 {
232				writeJSON(w, http.StatusConflict, map[string]any{
233					"error":           err.Error(),
234					"current_version": current,
235				})
236				return
237			}
238			writeError(w, http.StatusConflict, err.Error())
239		default:
240			writeError(w, http.StatusServiceUnavailable, "incident storage is unavailable; restart required")
241		}
242	}
243	
244	// readJSONObjectBody reads and strictly decodes a JSON object whose member
245	// names are all drawn from allowed. Syntax errors, non-objects, trailing
246	// data, duplicate keys, and unknown fields are reported as an error the
247	// caller turns into 400.
248	func readJSONObjectBody(w http.ResponseWriter, r *http.Request, allowed map[string]struct{}) (map[string]json.RawMessage, error) {
249		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxBodyBytes))
250		if err != nil {
251			return nil, err
252		}
253		return decodeStrictObject(body, allowed)
254	}
255	
256	// stringField returns the raw string member, or "" when absent, null, or not
257	// a JSON string; the domain layer then reports the empty field as 400.
258	func stringField(fields map[string]json.RawMessage, name string) string {
259		raw, present := fields[name]
260		if !present || bytes.Equal(raw, []byte("null")) {
261			return ""
262		}
263		var value string
264		if err := json.Unmarshal(raw, &value); err != nil {
265			return ""
266		}
267		return value
268	}
269	
270	// requiredString demands a present, non-null JSON string member.
271	func requiredString(w http.ResponseWriter, fields map[string]json.RawMessage, name string) (string, bool) {
272		raw, present := fields[name]
273		if !present || bytes.Equal(raw, []byte("null")) {
274			writeError(w, http.StatusBadRequest, name+" is required")
275			return "", false
276		}
277		var value string
278		if err := json.Unmarshal(raw, &value); err != nil {
279			writeError(w, http.StatusBadRequest, name+" has the wrong type")
280			return "", false
281		}
282		return value, true
283	}
284	
285	// decodeStrictInt accepts only a decimal integer literal: fractions (1.0),
286	// scientific notation (1e2), signs, booleans, and quoted numbers are a wrong
287	// type.
288	func decodeStrictInt(w http.ResponseWriter, raw json.RawMessage, name string, target *int64) bool {
289		if bytes.Equal(raw, []byte("null")) || !isDecimal(string(raw)) {
290			writeError(w, http.StatusBadRequest, name+" must be a positive integer")
291			return false
292		}
293		if err := json.Unmarshal(raw, target); err != nil {
294			writeError(w, http.StatusBadRequest, name+" must be a positive integer")
295			return false
296		}
297		return true
298	}
299	
300	type historyEntryDTO struct {
301		ActionID string `json:"action_id,omitempty"`
302		Operator string `json:"operator"`
303		Action   string `json:"action"`
304		Content  string `json:"content"`
305		Version  int    `json:"version"`
306		At       string `json:"at"`
307	}
308	
309	type incidentResponse struct {
310		ID           string            `json:"id"`
311		Title        string            `json:"title"`
312		Service      string            `json:"service"`
313		Status       string            `json:"status"`
314		Version      int               `json:"version"`
315		Participants []string          `json:"participants"`
316		Owner        string            `json:"owner"`
317		Events       []eventDTO        `json:"events"`
318		History      []historyEntryDTO `json:"history"`
319	}
320	
321	// writeIncident serializes one committed incident snapshot. Linked events
322	// are embedded in link order with their full stored content; the incident
323	// never owns or modifies them.
324	func writeIncident(w http.ResponseWriter, h *Handler, inc incidents.Incident) {
325		linked := h.timeline.EventsByID(inc.Links)
326		eventDTOs := eventsToDTOs(linked)
327		if eventDTOs == nil {
328			eventDTOs = []eventDTO{}
329		}
330	
331		history := make([]historyEntryDTO, len(inc.History))
332		for i, entry := range inc.History {
333			history[i] = historyEntryDTO{
334				ActionID: entry.ActionID,
335				Operator: entry.Operator,
336				Action:   entry.Action,
337				Content:  entry.Content,
338				Version:  entry.Version,
339				At:       utcRFC3339Nano(entry.At),
340			}
341		}
342	
343		participants := inc.Participants
344		if participants == nil {
345			participants = []string{}
346		}
347	
348		writeJSON(w, http.StatusOK, incidentResponse{
349			ID:           inc.ID,
350			Title:        inc.Title,
351			Service:      inc.Service,
352			Status:       inc.Status,
353			Version:      inc.Version,
354			Participants: participants,
355			Owner:        inc.Owner,
356			Events:       eventDTOs,
357			History:      history,
358		})
359	}
